WITH order_summary AS (SELECT order_id, COUNT(*) AS num_payments, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(method))) AS method_values FROM payments WHERE status IN ('FAILED', 'REFUNDED') GROUP BY order_id) SELECT o.channel, os.num_payments, os.method_values FROM orders o JOIN order_summary os ON o.id = os.order_id ORDER BY o.channel, method_values DESC;
